public interface IEntity { int Id { get; } }

public record Product(int Id, string Name, decimal Price) : IEntity;

public record Change<T>(string Kind, T? Before, T? After);

public class ValidationException(IReadOnlyList<string> errors) : Exception(string.Join("; ", errors))
{
    public IReadOnlyList<string> Errors { get; } = errors;
}

public class Repository<T> where T : class, IEntity
{
    private Dictionary<int, T> _items = new();
    private readonly List<Func<T, string?>> _rules = new();
    private Transaction? _open;

    public event EventHandler<Change<T>>? Changed;

    public int Count => _items.Count;

    public void AddRule(Func<T, string?> rule) => _rules.Add(rule);

    private void Validate(T item)
    {
        var errors = _rules.Select(rule => rule(item)).OfType<string>().ToList();
        if (errors.Count > 0) throw new ValidationException(errors);
    }

    private void Announce(Change<T> change)
    {
        if (_open != null) _open.Held.Add(change);
        else Changed?.Invoke(this, change);
    }

    public void Add(T item)
    {
        if (_items.ContainsKey(item.Id)) throw new InvalidOperationException($"duplicate id {item.Id}");
        Validate(item);
        _items[item.Id] = item;
        Announce(new Change<T>("added", null, item));
    }

    public void Update(T item)
    {
        if (!_items.TryGetValue(item.Id, out var before)) throw new KeyNotFoundException($"no item {item.Id}");
        Validate(item);
        _items[item.Id] = item;
        Announce(new Change<T>("updated", before, item));
    }

    public bool Remove(int id)
    {
        if (!_items.Remove(id, out var before)) return false;
        Announce(new Change<T>("removed", before, null));
        return true;
    }

    public T? Find(int id) => _items.GetValueOrDefault(id);

    public IEnumerable<T> Where(Func<T, bool> predicate)
    {
        foreach (var item in _items.Values.OrderBy(i => i.Id).ToList())
            if (predicate(item)) yield return item;
    }

    public IEnumerable<IReadOnlyList<T>> Pages(int size)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(size, 1);
        return Iterate();

        IEnumerable<IReadOnlyList<T>> Iterate()
        {
            var page = new List<T>(size);
            foreach (var item in _items.Values.OrderBy(i => i.Id).ToList())
            {
                page.Add(item);
                if (page.Count == size) { yield return page; page = new List<T>(size); }
            }
            if (page.Count > 0) yield return page;
        }
    }

    public Transaction BeginTransaction()
    {
        if (_open != null) throw new InvalidOperationException("a transaction is already open");
        _open = new Transaction(this, new Dictionary<int, T>(_items));
        return _open;
    }

    internal void EndTransaction(Transaction tx, bool commit)
    {
        if (!ReferenceEquals(_open, tx)) return;
        _open = null;
        if (commit) foreach (var change in tx.Held) Changed?.Invoke(this, change);
        else _items = tx.Snapshot;
    }

    public sealed class Transaction : IDisposable
    {
        private readonly Repository<T> _repo;
        private bool _finished;

        internal Transaction(Repository<T> repo, Dictionary<int, T> snapshot)
        {
            _repo = repo;
            Snapshot = snapshot;
        }

        internal Dictionary<int, T> Snapshot { get; }
        internal List<Change<T>> Held { get; } = new();

        public void Commit()
        {
            if (_finished) throw new InvalidOperationException("the transaction is finished");
            _finished = true;
            _repo.EndTransaction(this, commit: true);
        }

        public void Dispose()
        {
            if (_finished) return;
            _finished = true;
            _repo.EndTransaction(this, commit: false);
        }
    }
}

unitTests:
Repository<Product> Shop()
{
    var repo = new Repository<Product>();
    repo.AddRule(p => string.IsNullOrWhiteSpace(p.Name) ? "name is required" : null);
    repo.AddRule(p => p.Price < 0 ? "price must not be negative" : null);
    return repo;
}

Test("adding, finding and counting", () =>
{
    var repo = Shop();
    repo.Add(new Product(2, "Mug", 8m));
    repo.Add(new Product(1, "Tea", 2.5m));
    CheckEq(repo.Count, 2);
    CheckEq(repo.Find(1), new Product(1, "Tea", 2.5m));
    CheckEq(repo.Find(9), null);
    CheckThrows<InvalidOperationException>(() => repo.Add(new Product(1, "Other", 1m)));
});

Test("validation collects every error", () =>
{
    var repo = Shop();
    try
    {
        repo.Add(new Product(1, " ", -1m));
        Check(false, "should throw");
    }
    catch (ValidationException e)
    {
        CheckEq(e.Errors, new[] { "name is required", "price must not be negative" });
        CheckEq(e.Message, "name is required; price must not be negative");
    }
    CheckEq(repo.Count, 0);
    repo.Add(new Product(1, "Tea", 2m));
    CheckThrows<ValidationException>(() => repo.Update(new Product(1, "Tea", -2m)));
    CheckEq(repo.Find(1)!.Price, 2m);
    CheckThrows<KeyNotFoundException>(() => repo.Update(new Product(5, "X", 1m)));
});

Test("change events", () =>
{
    var repo = Shop();
    var log = new List<string>();
    repo.Changed += (_, c) => log.Add($"{c.Kind} {c.Before?.Name ?? "-"} -> {c.After?.Name ?? "-"}");
    repo.Add(new Product(1, "Tea", 2m));
    repo.Update(new Product(1, "Green tea", 3m));
    CheckEq(repo.Remove(1), true);
    CheckEq(repo.Remove(1), false);
    CheckEq(log, new[] { "added - -> Tea", "updated Tea -> Green tea", "removed Green tea -> -" });
});

Test("lazy queries and pages", () =>
{
    var repo = Shop();
    foreach (int id in new[] { 5, 3, 1, 4, 2 }) repo.Add(new Product(id, $"P{id}", id * 1.5m));
    var cheap = repo.Where(p => p.Price < 5m);
    repo.Add(new Product(0, "Free", 0m));
    CheckEq(cheap.Select(p => p.Id), new[] { 0, 1, 2, 3 });
    var pages = repo.Pages(4).ToList();
    CheckEq(pages.Count, 2);
    CheckEq(pages[0].Select(p => p.Id), new[] { 0, 1, 2, 3 });
    CheckEq(pages[1].Select(p => p.Id), new[] { 4, 5 });
    CheckThrows<ArgumentOutOfRangeException>(() => repo.Pages(0));
    CheckEq(new Repository<Product>().Pages(3).Count(), 0);
});

Test("committed transactions announce their changes", () =>
{
    var repo = Shop();
    repo.Add(new Product(1, "Tea", 2m));
    var log = new List<string>();
    repo.Changed += (_, c) => log.Add(c.Kind);
    using (var tx = repo.BeginTransaction())
    {
        repo.Add(new Product(2, "Mug", 8m));
        repo.Remove(1);
        CheckEq(repo.Count, 1);
        CheckEq(log.Count, 0);
        tx.Commit();
    }
    CheckEq(log, new[] { "added", "removed" });
    CheckEq(repo.Find(2)!.Name, "Mug");
});

Test("disposing without commit rolls back", () =>
{
    var repo = Shop();
    repo.Add(new Product(1, "Tea", 2m));
    int events = 0;
    repo.Changed += (_, _) => events++;
    using (repo.BeginTransaction())
    {
        repo.Update(new Product(1, "Coffee", 3m));
        repo.Add(new Product(2, "Mug", 8m));
        CheckEq(repo.Find(1)!.Name, "Coffee");
    }
    CheckEq(repo.Find(1)!.Name, "Tea");
    CheckEq(repo.Find(2), null);
    CheckEq(events, 0);
});

Test("transaction rules", () =>
{
    var repo = Shop();
    var tx = repo.BeginTransaction();
    CheckThrows<InvalidOperationException>(() => repo.BeginTransaction());
    tx.Commit();
    CheckThrows<InvalidOperationException>(() => tx.Commit());
    tx.Dispose();
    tx.Dispose();
    using var next = repo.BeginTransaction();
    repo.Add(new Product(1, "A", 1m));
    next.Dispose();
    CheckEq(repo.Count, 0);
    CheckThrows<InvalidOperationException>(() => next.Commit());
});

